example_item.example_item_data:
text = repmat('gzip ', 1, 100);
packed = nelson.io.gzip.compress(text, 'Level', 9);
[numel(text), numel(packed)]
isequal(nelson.io.gzip.decompresstext(packed), text)
nelson.io.gzip.version()

folder = tempname();
mkdir(folder);
source = fullfile(folder, 'gzip_example.txt');
filewrite(source, repmat(sprintf('line\n'), 1, 1000));
packed = nelson.io.gzip.compressfile(source)
delete(source);
restored = nelson.io.gzip.decompressfile(packed)
rmdir(folder, 's');

filename = [tempname(), '.gz'];
fid = nelson.io.gzip.fopen(filename, 'w');
fprintf(fid, 'line %d\n', 1:2);
fclose(fid);
fid = nelson.io.gzip.fopen(filename, 'a');
fprintf(fid, 'line %d\n', 3);
fclose(fid);
fid = nelson.io.gzip.fopen(filename);
first = fgetl(fid)
rest = fread(fid, [1, Inf], '*char')
fclose(fid);
delete(filename);

fid = nelson.io.gzip.fopen([], 'w');
fprintf(fid, '%d,%g\n', [1:3; (1:3) / 10]);
bytes = nelson.io.gzip.tobytes(fid);
fid = nelson.io.gzip.fopen(bytes);
C = textscan(fid, '%d,%f')
fclose(fid);
